window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-71475a0f3249dfb8"]={"versions": [{"id": "FIG-71475a0f3249dfb8", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Manifests (Bereich Deployment von Sicherheitsmechanismen). Das Diagramm modelliert die Konfiguration und das Deployment von SecOC (Secure Onboard Communication) durch Zuordnung von kryptografischen Anforderungen zu konkreten kryptografischen Jobs eines Krypto-Moduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>SecOcDeployment</code>: Spezialisierung von <code>SecureCommunicationDeployment</code>. Dient als Container und aggregiert über die Komposition <code>+secOcJobMapping</code> mit der Multiplizität <code>0..*</code> Instanzen von <code>SecOcJobMapping</code>.\n</li><li><code>SecOcJobMapping</code>: Von <code>Identifiable</code> abgeleitete Mapping-Klasse, die eine Anforderung mit einer Job-Realisierung verknüpft:\n<ul class=\"fig-list\"><li>Referenziert über die gerichtete Assoziation <code>+secOcJobRequirement</code> genau eine Instanz (<code>1</code>) von <code>SecOcJobRequirement</code>.\n</li><li>Referenziert über die gerichtete Assoziation <code>+job</code> genau eine Instanz (<code>1</code>) von <code>CryptoJob</code>.\n</li></ul>\n</li><li><code>SecOcJobRequirement</code>: Von <code>Identifiable</code> abgeleitete Entität. Definiert das Attribut <code>+secOcJobSemantic</code> vom Typ <code>SecOcJobSemanticEnum</code>.\n</li><li><code>CryptoModuleInstantiation</code>: Spezialisierung von <code>NonOsModuleInstantiation</code>. Aggregiert über die Komposition <code>+cryptoJob</code> mit Stereotyp <code>«atpSplitable»</code> und Multiplizität <code>0..*</code> Instanzen von <code>CryptoJob</code>.\n</li><li><code>CryptoJob</code>: Von <code>Identifiable</code> abgeleitetes Element, das einen konkreten Krypto-Job innerhalb der Modulinstanziierung repräsentiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches UML-Strukturmetamodell beschreibt das Diagramm keinen dynamischen Kontrollfluss oder Sequenzablauf zur Laufzeit. Es definiert die deklarative Konfigurationsstruktur im Manifest, anhand derer während des Modellierungs- bzw. Generierungsprozesses kryptografische Operationen von SecOC spezifischen CryptoJobs der Krypto-Modulinstanz zugeordnet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Metaklassen sind Teil des normativen Manifest-Schemas für die Adaptive Platform:</p>\n<ul class=\"fig-list\"><li>Jedes <code>SecOcJobMapping</code> erfordert zwingend exakt ein <code>SecOcJobRequirement</code> (<code>1</code>) sowie exakt einen zugeordneten <code>CryptoJob</code> (<code>1</code>).\n</li><li><code>SecOcJobRequirement</code> bestimmt über <code>SecOcJobSemanticEnum</code> semantisch die Rolle des Krypto-Jobs (z. B. MAC-Generierung oder -Verifikation).\n</li><li>Durch das Stereotyp <code>«atpSplitable»</code> an der Komposition <code>+cryptoJob</code> kann die Definition von Krypto-Jobs innerhalb der <code>CryptoModuleInstantiation</code> über mehrere ARXML-Dateien bzw. Paketfragmente aufgeteilt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e603ab68f00d32d5", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Manifests (Bereich Deployment von Sicherheitsmechanismen). Das Diagramm modelliert die Konfiguration und das Deployment von SecOC (Secure Onboard Communication) durch Zuordnung von kryptografischen Anforderungen zu konkreten kryptografischen Jobs eines Krypto-Moduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>SecOcDeployment</code>: Spezialisierung von <code>SecureCommunicationDeployment</code>. Dient als Container und aggregiert über die Komposition <code>+secOcJobMapping</code> mit der Multiplizität <code>0..*</code> Instanzen von <code>SecOcJobMapping</code>.\n</li><li><code>SecOcJobMapping</code>: Von <code>Identifiable</code> abgeleitete Mapping-Klasse, die eine Anforderung mit einer Job-Realisierung verknüpft:\n<ul class=\"fig-list\"><li>Referenziert über die gerichtete Assoziation <code>+secOcJobRequirement</code> genau eine Instanz (<code>1</code>) von <code>SecOcJobRequirement</code>.\n</li><li>Referenziert über die gerichtete Assoziation <code>+job</code> genau eine Instanz (<code>1</code>) von <code>CryptoJob</code>.\n</li></ul>\n</li><li><code>SecOcJobRequirement</code>: Von <code>Identifiable</code> abgeleitete Entität. Definiert das Attribut <code>+secOcJobSemantic</code> vom Typ <code>SecOcJobSemanticEnum</code>.\n</li><li><code>CryptoModuleInstantiation</code>: Spezialisierung von <code>NonOsModuleInstantiation</code>. Aggregiert über die Komposition <code>+cryptoJob</code> mit Stereotyp <code>«atpSplitable»</code> und Multiplizität <code>0..*</code> Instanzen von <code>CryptoJob</code>.\n</li><li><code>CryptoJob</code>: Von <code>Identifiable</code> abgeleitetes Element, das einen konkreten Krypto-Job innerhalb der Modulinstanziierung repräsentiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches UML-Strukturmetamodell beschreibt das Diagramm keinen dynamischen Kontrollfluss oder Sequenzablauf zur Laufzeit. Es definiert die deklarative Konfigurationsstruktur im Manifest, anhand derer während des Modellierungs- bzw. Generierungsprozesses kryptografische Operationen von SecOC spezifischen CryptoJobs der Krypto-Modulinstanz zugeordnet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Metaklassen sind Teil des normativen Manifest-Schemas für die Adaptive Platform:</p>\n<ul class=\"fig-list\"><li>Jedes <code>SecOcJobMapping</code> erfordert zwingend exakt ein <code>SecOcJobRequirement</code> (<code>1</code>) sowie exakt einen zugeordneten <code>CryptoJob</code> (<code>1</code>).\n</li><li><code>SecOcJobRequirement</code> bestimmt über <code>SecOcJobSemanticEnum</code> semantisch die Rolle des Krypto-Jobs (z. B. MAC-Generierung oder -Verifikation).\n</li><li>Durch das Stereotyp <code>«atpSplitable»</code> an der Komposition <code>+cryptoJob</code> kann die Definition von Krypto-Jobs innerhalb der <code>CryptoModuleInstantiation</code> über mehrere ARXML-Dateien bzw. Paketfragmente aufgeteilt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-71475a0f3249dfb8", "to": "FIG-e603ab68f00d32d5", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
